import type { TroubleCodeGuide } from "./trouble-code-data";

const manuals={label:"Toyota Corolla manuals and warranty guides",url:"https://www.toyota.com/owners/warranty-owners-manuals/",note:"Official Toyota model-year owner-document lookup; use VIN- and engine-correct Toyota repair information"};
const coldMisfire={label:"Toyota T-SB-0010-24 Rev2 — cold-temperature misfire",url:"https://static.nhtsa.gov/odi/tsbs/2025/MC-11020670-0001.pdf",note:"2019–2025 Corolla M20A-FKS applications listed by production range; complete normal misfire diagnosis before the bulletin repair"};
const hatchFuel={label:"Toyota T-SB-0009-23 — loss of fuel pressure",url:"https://static.nhtsa.gov/odi/tsbs/2023/MC-10235216-9999.pdf",note:"2019–2020 Corolla Hatchback M20A-FKS only; P0171/P0087 or hard-start condition requires measured fuel-pressure evidence"};

const vehicle={name:"Toyota Corolla",kicker:"TOYOTA COROLLA · ENGINE AND EMISSIONS DIAGNOSTICS",breadcrumb:"Toyota Corolla",about:"Toyota Corolla engine and emissions diagnostics",yearsIntro:"Corolla covers several distinct diagnostic families: older 1ZZ-FE cable/electronic-throttle cars, 2ZR-FE/2ZR-FAE sedans, 2019+ M20A-FKS Hatchback and higher-output trims, later 2.0L sedans, and 2ZR-FXE hybrids. Confirm body style, model year, VIN, engine code, hybrid status, emissions certification and calibration before using specifications or a Toyota bulletin."};
type Input=Omit<TroubleCodeGuide,"slug"|"vehicle">&{slug:string};
const article=(x:Input):TroubleCodeGuide=>({...x,slug:`toyota/corolla/${x.slug}`,vehicle});

export const troubleCodeCorolla:TroubleCodeGuide[]=[
article({slug:"p0420",code:"P0420",title:"P0420 Code Toyota Corolla: Catalyst Diagnosis Before Replacement",description:"Diagnose Corolla P0420 by checking misfire, fuel trims, oil use, exhaust leaks and sensor response before testing the Bank 1 catalytic converter.",definition:"Catalyst System Efficiency Below Threshold (Bank 1)",severity:"Service soon",driveAdvice:"A steady P0420 with normal power usually allows a short diagnostic trip. Stop if the check-engine light flashes, the exhaust smells strongly of raw fuel, the converter glows or overheats, or power drops as though the exhaust is blocked. Those symptoms can turn a monitor fault into expensive engine or catalyst damage.",quickAnswer:"P0420 means the ECM calculated that the Bank 1 catalyst stored less oxygen than its calibration expects. On every four-cylinder Corolla, Bank 1 is the only cylinder bank. The code does not say what reduced catalyst performance. Historical misfire, rich or lean operation, oil burning, coolant entry, an exhaust leak, sensor wiring or an incorrectly specified replacement converter must be investigated before the converter becomes a defensible diagnosis.",symptoms:[{key:"lamp",label:"Lamp on, car drives normally",response:"Preserve readiness and freeze frame; test monitor prerequisites rather than replacing a sensor from one code."},{key:"flash",label:"Lamp flashes before P0420",response:"Stop load and diagnose the active misfire first; raw fuel can overheat the catalyst."},{key:"oil",label:"Oil consumption or blue smoke",response:"Find the oil-entry source before fitting a converter that may be contaminated again."},{key:"power",label:"Poor high-rpm power or exhaust rattle",response:"Inspect for broken substrate and test restriction with Toyota's specified method."},{key:"repeat",label:"P0420 returned after replacement",response:"Audit emissions certification, unresolved fueling/misfire, exhaust leaks and sensor circuits."}],causes:[{cause:"Catalyst oxygen-storage capacity depleted",evidence:"All prerequisites pass and Toyota's efficiency test fails",firstTest:"Run engine- and emissions-specific catalyst monitor diagnosis"},{cause:"Misfire or rich/lean operation damaged the catalyst",evidence:"Historical codes, abnormal trims or plug deposits",firstTest:"Resolve upstream fuel and ignition faults before catalyst testing"},{cause:"Oil or coolant contamination",evidence:"Consumption, smoke, coolant loss or characteristic deposits",firstTest:"Mechanical and cooling-system diagnosis"},{cause:"Exhaust leak around upstream/downstream sensors",evidence:"Cold tick, soot or leakage during a safe test",firstTest:"Inspect cold and leak-test the Bank 1 exhaust"},{cause:"A/F or downstream oxygen-sensor circuit fault",evidence:"Controlled response or wiring test fails",firstTest:"Graph both sensors and test power, ground and signal paths"}],freezeFrame:["RPM, load, speed and coolant temperature","Fuel-system status plus short- and long-term trim","Misfire and mixture-code history","Upstream A/F and downstream oxygen-sensor data","Oil/coolant consumption and exhaust-repair history","Emissions label and readiness state"],steps:[{title:"Keep the evidence",detail:"Save confirmed, pending and permanent codes plus readiness before clearing."},{title:"Repair upstream faults",detail:"Resolve P0300, P0171, rich operation and circuit codes before judging the catalyst."},{title:"Inspect contamination and leaks",detail:"Check oil/coolant use and the complete Bank 1 exhaust path."},{title:"Test sensor response",detail:"Use Toyota data definitions; do not judge the converter from one warm-idle snapshot."},{title:"Evaluate storage and restriction",detail:"Apply the exact engine/emissions repair-manual tests only after prerequisites pass."},{title:"Complete the monitor",detail:"Drive under safe enable conditions and confirm no pending P0420."}],dontReplace:"Do not replace the converter or downstream sensor from one P0420. The converter may be the casualty rather than the cause, and a replacement can fail again if misfire, fuel control or oil consumption remains.",yearNotes:["All common U.S. Corolla engines in this scope are inline-fours, so Bank 1 is the only bank; Sensor 2 is downstream of the catalyst.","Federal, California and PZEV emissions packages can require different legal converters and warranty coverage.","Hybrid engine cycling changes monitor opportunities: READY time is not continuous engine run time.","No broad Toyota Corolla P0420 replacement bulletin is cited; use the current VIN-specific diagnostic tree."],faqs:[{question:"Does P0420 always mean a bad converter?",answer:"No. Exhaust leaks, sensor/circuit faults and upstream engine problems must be excluded."},{question:"Which bank is Bank 1 on a Corolla?",answer:"The inline-four has only one cylinder bank, designated Bank 1."},{question:"Can I keep driving?",answer:"Usually briefly if the code is alone; stop for flashing misfire, raw fuel or severe power loss."},{question:"Can an oxygen sensor cause P0420?",answer:"A failed or biased sensor can affect the monitor, but it must fail a controlled test."},{question:"Can oil burning damage the converter?",answer:"Yes. Phosphorus and ash contamination can reduce catalyst activity."},{question:"Will a catalyst cleaner fix it?",answer:"An additive cannot restore melted substrate or depleted catalyst material."},{question:"Why did P0420 return after converter replacement?",answer:"An upstream cause, leak, wrong emissions application or sensor fault may remain."},{question:"What proves the repair?",answer:"Normal engine control and a completed catalyst monitor without pending P0420."}],deepDive:[{heading:"Read the code history before looking at the converter",paragraphs:["A previous flashing P0300, long-term rich correction or chronic oil use can explain how the catalyst lost capacity. Pull permanent and historical information before clearing; otherwise the event that damaged the converter may disappear from view.","Inspect plugs, tailpipe deposits, coolant level and oil-consumption records. A clean current fuel-trim snapshot cannot prove the engine was healthy during the thousands of miles that aged the catalyst."]},{heading:"Why similar oxygen-sensor traces are not a complete test",paragraphs:["A downstream signal that resembles the upstream signal can support low oxygen storage, but sample rate, operating state, exhaust leaks and sensor condition matter. Apply Toyota's enable conditions and test logic instead of using a social-media waveform as a universal threshold.","If the replacement decision is expensive, ask the technician to document sensor response, exhaust integrity, readiness and the test that eliminated upstream causes."]},{heading:"Corolla emissions application matters at the parts counter",paragraphs:["Use the underhood emissions label and VIN to determine federal, California or PZEV certification. Physical fit does not prove a converter has the correct precious-metal loading or legal approval for the vehicle.","Check applicable federal or state emissions warranty before authorizing a customer-pay converter. A bulletin, warranty and recall are different programs."]}],sources:[manuals]}),
article({slug:"p0171",code:"P0171",title:"P0171 Code Toyota Corolla: Fuel-Trim Diagnosis by Engine",description:"Diagnose Corolla P0171 with idle-versus-load trims, smoke and purge tests, exhaust inspection and measured fuel pressure—including Hatchback limits.",definition:"System Too Lean (Bank 1)",severity:"Diagnose promptly",driveAdvice:"Avoid sustained high load until fuel delivery and misfire are checked. Stop for a flashing lamp, detonation, severe hesitation, stalling or overheating. A steady lamp on a smooth-running Corolla may allow a short diagnostic trip, but excessive lean correction should not be ignored.",quickAnswer:"P0171 means the ECM had to add more fuel than its calibrated Bank 1 limit. A Corolla inline-four has only Bank 1. The code is not an oxygen-sensor verdict. Compare correction at idle and higher airflow; smoke-test the intake, PCV and brake-booster paths; test purge sealing and upstream exhaust leakage; then verify MAF response and fuel pressure. Toyota T-SB-0009-23 adds a measured-pressure branch only for listed 2019–2020 Corolla Hatchbacks—not every Corolla sedan.",symptoms:[{key:"idle",label:"Trim is highest at idle",response:"Prioritize unmetered intake/PCV air and purge flow with a smoke/seal test."},{key:"load",label:"Lean correction grows with load",response:"Measure fuel pressure/volume and verify MAF response before replacing sensors."},{key:"start",label:"Hard start plus P0087",response:"On an eligible 2019–2020 Hatchback, check fuel pressure and bulletin applicability."},{key:"refuel",label:"Rough after refueling",response:"Test purge physical sealing when commanded closed."},{key:"cold",label:"Only lean after cold start",response:"Compare ECT/IAT to ambient and inspect temperature-sensitive gasket leakage."}],causes:[{cause:"Intake, PCV or booster vacuum leak",evidence:"Positive trim strongest at idle; smoke escapes",firstTest:"Regulated smoke test downstream of the MAF"},{cause:"Purge valve leaking into the intake",evidence:"Post-refuel symptom or flow with command off",firstTest:"Bidirectional command and independent seal test"},{cause:"Low fuel pressure or injector delivery",evidence:"Correction rises with demand, P0087 or hard start",firstTest:"Measure pressure using the exact engine procedure"},{cause:"Exhaust leak before the A/F sensor",evidence:"Cold tick/soot with false-lean response",firstTest:"Inspect cold and leak-test safely"},{cause:"MAF or A/F-sensor bias/circuit fault",evidence:"Leaks and fuel pass; controlled response fails",firstTest:"Plausibility and circuit tests using Toyota data"}],freezeFrame:["Short- and long-term fuel trim","RPM, load, speed and coolant temperature","MAF, MAP and throttle angle","Fuel pressure or P0087 companion data","Purge command and time since refueling","Cold-soak ECT/IAT plausibility"],steps:[{title:"Save the shape of the fault",detail:"Record trims at the stored condition before clearing."},{title:"Compare idle and higher airflow",detail:"Use how correction changes to separate air leakage from delivery."},{title:"Smoke-test and isolate purge",detail:"Test physical leakage, not only electrical clicking."},{title:"Inspect upstream exhaust",detail:"A leak can draw oxygen and create a false lean report."},{title:"Measure fuel and sensor performance",detail:"Apply Hatchback fuel-pump guidance only after matching the table."},{title:"Verify in the original condition",detail:"Confirm normal correction and no pending return."}],dontReplace:"Do not install an upstream A/F sensor, MAF or fuel pump because P0171 is stored. T-SB-0009-23 requires an eligible Hatchback and measured low pressure; it does not cover every Corolla carrying the nameplate.",yearNotes:["T-SB-0009-23 includes listed 2019–2020 Corolla Hatchback M20A-FKS applications with hard start and/or P0171/P0174/P0087.","The bulletin is not blanket coverage for Corolla sedans, older 1ZZ/2ZR engines or Corolla Hybrid.","2ZR-FE/2ZR-FAE and M20A-FKS use different airflow and fuel-pressure specifications.","A basic reader may label every Toyota lean code generically; preserve Toyota subcodes and companion data when available."],faqs:[{question:"Does P0171 mean the oxygen sensor is bad?",answer:"No. The sensor may be correctly reporting unmetered air or low fuel delivery."},{question:"Can a vacuum leak cause it?",answer:"Yes, especially if correction is greatest at warm idle."},{question:"Can a fuel pump cause P0171?",answer:"Yes when measured delivery is low; Toyota documents a narrow Hatchback population."},{question:"Does the Hatchback bulletin cover my sedan?",answer:"No. Applicability must match model/body style, year and engine."},{question:"Can purge cause a lean code?",answer:"Unexpected vapor and air flow can upset idle fuel control."},{question:"Can I drive?",answer:"Limit load and diagnose promptly; stop for misfire or severe hesitation."},{question:"Should I clean the MAF?",answer:"Only after intake inspection and with an approved method; cleaning is not a diagnosis."},{question:"What proves repair?",answer:"Normal trims at idle and load with no pending P0171."}],deepDive:[{heading:"Fuel-trim movement is more useful than a parts list",paragraphs:["Correction that drops substantially when rpm rises points toward air entering around the throttle, intake gasket, PCV or purge path. Correction that worsens under demand puts measured airflow and fuel delivery higher.","Record units and both short- and long-term values. A recently cleared ECM may have little learned correction, so short-term behavior and freeze frame carry more weight."]},{heading:"How to use the Corolla Hatchback fuel-pump bulletin",paragraphs:["First match the body style, model year, engine and symptoms. Toyota's procedure then calls for fuel-pressure inspection; the code alone does not authorize pump replacement.","If pressure passes or the vehicle is a sedan/hybrid/other year, return to the applicable repair manual. Do not use an internet summary to stretch coverage."]},{heading:"A/F sensor replacement comes late",paragraphs:["An upstream A/F sensor should respond plausibly to controlled mixture changes and pass wiring checks. It should not be condemned for accurately reporting oxygen entering through an intake or exhaust leak.","After repair, repeat both idle and safe higher-airflow checks. One good warm-idle number does not close a load-dependent fuel fault."]}],sources:[hatchFuel,manuals]}),
article({slug:"p0441",code:"P0441",title:"P0441 Code Toyota Corolla: EVAP Purge-Flow Diagnosis",description:"Diagnose Corolla P0441 with original fuel-cap evidence, purge and vent commands, tank-pressure response, regulated smoke and generation-correct EVAP routing.",definition:"Evaporative Emission Control System Incorrect Purge Flow",severity:"Service soon",driveAdvice:"P0441 alone usually allows normal short-term driving. Stop and inspect for liquid fuel leakage, a strong vapor odor, stalling or severe hard-start after refueling. EVAP diagnosis involves fuel vapor: work with ventilation, avoid ignition sources and never apply unrestricted shop air.",quickAnswer:"P0441 means the ECM commanded an EVAP test but did not observe the pressure or flow response expected for that Corolla's strategy. It does not name a purge valve. A cap/filler leak, purge VSV that leaks or cannot flow, vent/closed-valve fault, restricted hose, saturated canister, tank-pressure sensor bias or incorrect routing can all change the result. Older vacuum-switching-valve systems and later leak-detection-pump systems require different isolation sequences.",symptoms:[{key:"refuel",label:"Hard start after filling",response:"Test purge for physical leakage into the intake while commanded off."},{key:"cap",label:"Code followed a fuel stop",response:"Document the cap's original state and inspect its seal/filler surface."},{key:"odor",label:"Fuel-vapor smell",response:"Inspect promptly for liquid or vapor leakage and avoid sparks."},{key:"click",label:"Purge valve clicks",response:"A click proves movement, not correct flow rate or sealing."},{key:"none",label:"No drivability symptoms",response:"Use fuel-level context, valve commands and tank-pressure data."}],causes:[{cause:"Purge VSV leaking, restricted or electrically faulty",evidence:"Command and measured flow/seal do not agree",firstTest:"Command test plus independent physical seal/flow check"},{cause:"Fuel cap, filler or system leak",evidence:"Seal damage or regulated smoke escape",firstTest:"Document cap then smoke-test at EVAP pressure"},{cause:"Vent/closed-valve or leak-detection-pump fault",evidence:"Tank pressure fails the commanded sequence",firstTest:"Test generation-specific valve/pump and circuit"},{cause:"Saturated canister or restricted vapor line",evidence:"Topping-off history, liquid fuel or abnormal flow",firstTest:"Inspect routing and canister without shop-air pressure"},{cause:"Tank-pressure sensor bias or hose misrouting",evidence:"Implausible response or recent service",firstTest:"Controlled response and diagram comparison"}],freezeFrame:["Fuel level and time since refueling","Ambient and coolant temperature","Purge and vent commands","Fuel-tank pressure or vapor-pressure data","Companion P0440/P0442/P0455/P0456 codes","Recent cap, tank or engine-bay work"],steps:[{title:"Do not disturb the evidence",detail:"Record cap state, fuel level, freeze frame and companion codes."},{title:"Identify the EVAP generation",detail:"Map the exact purge, vent, canister and pump/pressure-sensor layout."},{title:"Test purge electrically and physically",detail:"Verify command, flow and sealing as separate questions."},{title:"Observe tank-pressure response",detail:"Control the other EVAP path according to Toyota's sequence."},{title:"Use regulated smoke",detail:"Inspect each quick-connect, hose, canister, filler and tank seam."},{title:"Run the monitor correctly",detail:"Meet fuel-level/soak conditions and check pending status."}],dontReplace:"Do not replace the purge valve solely because P0441 contains 'purge flow.' The monitor evaluates a system response, so a leak, restriction, vent fault or biased pressure signal can imitate purge failure.",yearNotes:["North American Corolla EVAP layouts changed substantially between early 2000s cars, later 2ZR vehicles and current TNGA models.","Corolla Hybrid hardware and engine cycling require the exact hybrid repair manual.","Search results commonly surface Mazda or Volkswagen P0441 bulletins; those documents do not apply to Toyota Corolla.","No broad Corolla P0441 parts bulletin is cited here."],faqs:[{question:"Is P0441 always a bad purge valve?",answer:"No. It is an incorrect system-flow response, not a named-part verdict."},{question:"Can the gas cap cause it?",answer:"A sealing fault can affect some Toyota EVAP tests, but must be inspected and tested."},{question:"Why does it start hard after refueling?",answer:"A purge valve leaking into the intake can create an overly rich start."},{question:"Does a clicking valve pass?",answer:"No. It must also seal and flow correctly."},{question:"Can I drive?",answer:"Usually briefly if alone; stop for liquid fuel, strong odor or stalling."},{question:"How is the fault found?",answer:"With commands, tank-pressure data and regulated smoke testing."},{question:"Can topping off matter?",answer:"Yes. Liquid fuel can saturate the charcoal canister."},{question:"What proves repair?",answer:"Correct commanded response and a completed EVAP monitor without pending P0441."}],deepDive:[{heading:"Preserve the cap and refueling evidence",paragraphs:["Before tightening anything, note whether the cap was loose, its seal is cut or the filler surface is damaged. Correcting the cap before reading freeze frame can erase the only useful clue.","Fuel level is not trivia: EVAP monitors operate within calibrated ranges, and liquid expansion in a nearly full tank changes test behavior."]},{heading:"Electrical operation is not vapor control",paragraphs:["A purge VSV can click yet leak at zero command or fail to pass the intended flow. Test command voltage/current and physical sealing separately. Apply the same principle to the vent or leak-detection hardware.","When pressure response is wrong, isolate one path at a time instead of replacing every valve. Use Toyota's generation-correct hose diagram so ports are not accidentally reversed."]},{heading:"Smoke-test without damaging the system",paragraphs:["Use an EVAP-approved machine and the regulated pressure specified in service information. Unrestricted shop air can damage the canister, sensor or tank.","Watch small seams patiently and move flexible lines gently. Finish by confirming the monitor completes; clearing the lamp alone does not test purge flow."]}],sources:[manuals]}),
article({slug:"p0455",code:"P0455",title:"P0455 Code Toyota Corolla: Large EVAP Leak Testing",description:"Find Corolla P0455 using cap and filler inspection, regulated smoke, purge/vent sealing, tank-pressure response and generation-specific routing.",definition:"Evaporative Emission System Leak Detected (Gross Leak/No Flow)",severity:"Service soon",driveAdvice:"P0455 by itself normally permits a short trip, but stop for visible liquid fuel, strong vapor odor, stalling or severe post-refuel trouble. Keep flame, sparks and hot work away from the car until leakage is excluded.",quickAnswer:"P0455 means the Corolla's EVAP monitor could not establish or hold its expected vacuum/pressure and interpreted the result as a gross leak or no-flow condition. A loose or wrong cap, disconnected hose, purge or vent valve stuck open, cracked canister, filler/tank seal, pressure-sensor bias or restriction can all look 'large' to the monitor. The code does not identify the opening.",symptoms:[{key:"after",label:"Appeared after refueling",response:"Document cap engagement and inspect the seal and filler neck before clearing."},{key:"odor",label:"Strong vapor odor",response:"Inspect promptly for liquid/vapor leakage and avoid ignition sources."},{key:"stall",label:"Hard start or stall after filling",response:"Test purge physical sealing into the intake."},{key:"other",label:"P0441 or vent code also stored",response:"Treat valve sequence and tank-pressure behavior as one diagnosis."},{key:"none",label:"Lamp only",response:"Use EVAP-regulated smoke; visual inspection alone often misses the path."}],causes:[{cause:"Missing, loose, incorrect or damaged cap",evidence:"Original cap state or sealing damage",firstTest:"Document, inspect and verify correct cap/filler"},{cause:"Disconnected, split or rodent-damaged vapor hose",evidence:"Visible opening or smoke leakage",firstTest:"Inspect accessible routing then regulated smoke"},{cause:"Purge or vent path cannot seal",evidence:"Flow remains with closed command",firstTest:"Bidirectional command and independent sealing tests"},{cause:"Canister, pump-module, filler or tank seal leak",evidence:"Smoke at component seam",firstTest:"Isolate exact tank layout at regulated pressure"},{cause:"Pressure sensor bias or EVAP blockage",evidence:"Implausible tank response or no expected flow",firstTest:"Controlled sensor response and line-flow test"}],freezeFrame:["Fuel level, ambient temperature and soak time","Purge/vent commands and tank-pressure data","Time since refueling","Companion EVAP codes","Cap/filler and underbody damage history","Readiness before code clearing"],steps:[{title:"Record the original condition",detail:"Keep cap state, freeze frame and fuel level."},{title:"Identify system layout",detail:"Use the exact Corolla year/engine/hybrid diagram."},{title:"Inspect easy large openings",detail:"Check cap, filler and accessible hoses/quick-connects."},{title:"Control purge and vent",detail:"Test electrical command and physical sealing separately."},{title:"Smoke at regulated pressure",detail:"Inspect the canister, tank, pump-module and every seam."},{title:"Verify monitor completion",detail:"Meet enable conditions and check pending codes."}],dontReplace:"Do not call every P0455 a gas cap or replace the canister by association. A valve held open can appear as a gross leak, while a canister should be condemned only after a leak or contamination test.",yearNotes:["The meaning 'gross leak/no flow' describes monitor magnitude, not a guaranteed hole size.","Later Corolla leak-detection-pump systems do not use the same isolation sequence as early vacuum-switching-valve systems.","Hybrid fuel and vapor hardware can differ from the gasoline sedan/hatchback.","No broad Corolla P0455 replacement bulletin is cited."],faqs:[{question:"Is P0455 always a loose gas cap?",answer:"No. Hoses, valves, canister and tank/filler seals are also possible."},{question:"Can I drive?",answer:"Usually briefly if the code is alone; not with liquid fuel or strong vapor odor."},{question:"Can purge cause a large-leak code?",answer:"Yes, if the valve cannot seal during the monitor."},{question:"How is a large leak found?",answer:"With valve commands, tank-pressure response and regulated smoke."},{question:"Why did a new cap not fix it?",answer:"The cap may not have been the leak, may be wrong, or another fault remains."},{question:"Can topping off cause damage?",answer:"Yes, liquid fuel can saturate the canister."},{question:"Why will readiness not complete?",answer:"Fuel level, soak or temperature may be outside monitor conditions."},{question:"What proves repair?",answer:"The system seals and completes its EVAP monitor without pending P0455."}],deepDive:[{heading:"Large leak and no flow require different thinking",paragraphs:["The same code family can mature because the system cannot hold vacuum or because the expected test flow never develops. Look at tank-pressure movement and companion valve codes before assuming a physical opening.","A disconnected hose often reveals itself quickly; a valve that will not seal needs command and isolation testing. The scan data tells you which path deserves priority."]},{heading:"Inspect the underside after impact or animal damage",paragraphs:["Road debris, jack placement and rodents can damage vapor lines above or near the tank. Ask when the lamp appeared and inspect clips/quick-connects before lowering the tank.","Strong vapor odor requires prompt safety inspection even if the car drives normally. The diagnostic code measures monitor behavior, not the actual concentration around the vehicle."]},{heading:"A completed monitor closes the repair",paragraphs:["EVAP readiness may need a cold soak, a calibrated fuel-level window and temperature stability. Do not repeatedly clear memory while waiting; each reset restarts readiness.","After the monitor passes, recheck for physical fuel/vapor leakage. A passing monitor is important evidence, but safety inspection remains separate."]}],sources:[manuals]}),
article({slug:"p0300",code:"P0300",title:"P0300 Code Toyota Corolla: Misfire Diagnosis and Cold-Weather Bulletin",description:"Diagnose Corolla P0300 with cylinder counters, ignition, injector and compression tests plus exact M20A-FKS cold-weather bulletin boundaries.",definition:"Random/Multiple Cylinder Misfire Detected",severity:"Stop soon",driveAdvice:"A flashing check-engine light signals an active catalyst-damaging misfire. Release the throttle and stop safely rather than repeating a load test. A steady lamp with smooth operation may allow a short trip for diagnosis, but stop for severe shaking, raw-fuel odor, mechanical noise, overheating or loss of oil pressure.",quickAnswer:"P0300 means the ECM detected crankshaft-speed variation consistent with misfire across multiple cylinders or without one cylinder dominating. It does not mean four coils failed. Save P0301–P0304 subcodes, counters and freeze frame, then classify a fixed-cylinder, paired-cylinder or whole-engine pattern. Toyota T-SB-0010-24 Rev2 adds a narrow cold-temperature path for listed 2019–2025 Corolla M20A-FKS production ranges only after normal misfire diagnosis.",symptoms:[{key:"flash",label:"Lamp flashes under acceleration",response:"Stop load immediately; do not repeat the event to collect more data."},{key:"cold",label:"Only misfires in cold weather",response:"Capture early counters and verify M20A-FKS bulletin year/production applicability."},{key:"one",label:"One cylinder consistently leads",response:"Inspect its plug/coil, then injector contribution and mechanical sealing."},{key:"several",label:"Several cylinders rise together",response:"Prioritize shared fuel pressure, air, voltage, purge or timing conditions."},{key:"hybrid",label:"Engine starts and stops in hybrid operation",response:"Distinguish normal hybrid cycling from rough restart using engine-run data."}],causes:[{cause:"Worn/fouled plug, coil, boot or connector",evidence:"Counter follows one controlled swap or plug differs",firstTest:"Inspect plugs in order and move one known-good coil"},{cause:"Injector or fuel-pressure problem",evidence:"Ignition passes; contribution/pressure fails",firstTest:"Engine-specific pressure and injector tests"},{cause:"Intake/PCV leak or uncontrolled purge",evidence:"Trim, smoke or refueling evidence",firstTest:"Smoke-test intake and verify purge sealing"},{cause:"Compression, valve, coolant-entry or timing fault",evidence:"Counter stays with cylinder or mechanical evidence",firstTest:"Compression/leak-down and cam/timing checks"},{cause:"Cold-temperature condition on covered M20A-FKS",evidence:"Exact production match, cold event and normal base diagnosis",firstTest:"Apply T-SB-0010-24 sequence and calibration/parts checks"}],freezeFrame:["P0301–P0304 subcodes and cylinder counters","Coolant and intake-air temperature at first start","RPM, load, speed and battery voltage","Fuel trims and commanded/actual pressure","Cam/VVT and circuit companion codes","Fuel quality, recent repair and cold-weather history"],steps:[{title:"Preserve the cylinder story",detail:"Save counters and freeze frame before clearing or swapping parts."},{title:"Classify the pattern",detail:"Separate one cylinder from shared multi-cylinder behavior."},{title:"Test ignition one variable at a time",detail:"Read plugs and use one controlled coil swap."},{title:"Move to fuel and air",detail:"Measure pressure/contribution and test intake/purge paths."},{title:"Measure mechanical condition",detail:"Use compression, leakage and timing data when the fault stays."},{title:"Apply and verify the bulletin narrowly",detail:"Match M20A-FKS production range and reproduce only a safe cold condition."}],dontReplace:"Do not install four coils or treat every cold Corolla misfire as T-SB-0010-24. Toyota's bulletin lists specific M20A-FKS years and production ranges and directs normal misfire diagnosis before its repair procedure.",yearNotes:["T-SB-0010-24 Rev2 lists 2019–2025 Corolla M20A-FKS applications by production range and concerns misfire DTCs in cold temperatures.","The bulletin does not automatically cover older 1ZZ/2ZR engines, Corolla Hybrid 2ZR-FXE or every 2025 build.","A flashing lamp overrides bulletin research: stop the catalyst-damaging event first.","Preserve Toyota five-/six-digit subcodes when the scan tool supports them; they add failure-mode detail."],faqs:[{question:"Does P0300 mean all coils are bad?",answer:"No. Air, fuel, injector, compression, timing and voltage faults can cause it."},{question:"Can I drive with P0300?",answer:"Stop for a flashing lamp or severe shaking; otherwise limit driving until diagnosed."},{question:"How do I identify the cylinder?",answer:"Use P0301–P0304, counters and Mode $06 under the setting condition."},{question:"Does Toyota have a cold-weather bulletin?",answer:"Yes, for listed 2019–2025 M20A-FKS production ranges after base diagnosis."},{question:"Does it cover every Corolla?",answer:"No. Engine, year and production range must match."},{question:"Can a fuel pump cause multiple misfires?",answer:"Low pressure can, especially when counts rise with load."},{question:"Should I clear the code first?",answer:"No. Save the original freeze frame and counters."},{question:"What proves repair?",answer:"Stable counters and no pending misfire under the original safe condition."}],deepDive:[{heading:"The first cold minute carries the best evidence",paragraphs:["Record coolant and intake-air temperature before the engine warms, then watch which cylinders accumulate counts. Once heat changes mixture, sealing and vaporization, the fault may disappear along with its clues.","Do not repeatedly provoke a flashing lamp. One controlled observation plus stored Toyota subcodes is more useful than a long damaging road test."]},{heading:"How T-SB-0010-24 changes—not replaces—the workflow",paragraphs:["Toyota's repair procedure begins after the normal misfire diagnostic path and only for the listed M20A-FKS population. Match production date and calibration; similar winter symptoms on a 2ZR do not extend the bulletin.","Keep the base-test results. If a coil, injector, low compression or fuel problem is proven, that physical fault remains the diagnosis even when the year appears in a bulletin table."]},{heading:"One-cylinder and multi-cylinder cases split early",paragraphs:["A count that follows a controlled coil swap supports ignition. A count that stays on one hole requires injector contribution and compression/leak-down. Similar counts across cylinders suggest shared supply, air, timing or voltage.","After repair, check pending codes and counters on the next naturally cold start. Clearing the lamp while the weather is warm does not verify a cold-only fix."]}],sources:[coldMisfire,manuals]}),
article({slug:"p0016",code:"P0016",title:"P0016 Code Toyota Corolla: Cam-Crank Correlation Diagnosis",description:"Diagnose Corolla P0016 with oil and VVT checks, desired-versus-actual cam angle, synchronized waveforms and engine-specific mechanical timing verification.",definition:"Crankshaft Position–Camshaft Position Correlation (Bank 1, Sensor A)",severity:"Stop soon",driveAdvice:"Keep driving to a minimum until oil pressure, timing noise and starting behavior are checked. Stop for persistent chain or actuator rattle, hard starting, stalling or a low-oil-pressure warning. Repeatedly starting or revving an engine that may be mechanically out of time risks additional damage.",quickAnswer:"P0016 means the ECM found the Bank 1 intake-cam signal outside its expected relationship to the crankshaft. On Corolla inline-fours, there is one bank; 'Sensor A' normally identifies the intake cam. It does not mean the cam sensor failed. Oil condition and pressure, VVT oil control, actuator operation, wiring, reluctors, mechanical chain timing and recent repair errors all affect the relationship, and 1ZZ, 2ZR and M20A procedures are not interchangeable.",symptoms:[{key:"rattle",label:"Rattle during startup",response:"Stop repeated starts and verify oil pressure plus mechanical timing before electrical guessing."},{key:"after",label:"Code began after engine work",response:"Recheck chain indexing, reluctors, connectors, grounds and learned values."},{key:"oil",label:"Oil level or grade is wrong",response:"Correct it and test VVT response; do not assume oil service repairs a jumped chain."},{key:"multi",label:"Several VVT/correlation codes",response:"Prioritize shared oil supply, crank signal, power/ground or installation faults."},{key:"stall",label:"Hard start, stall or poor power",response:"Limit operation and confirm physical timing before loaded testing."}],causes:[{cause:"Incorrect mechanical timing or worn chain components",evidence:"Stable phase offset, noise or recent timing work",firstTest:"Verify timing with the exact engine's marks/tools"},{cause:"Low, aerated, dirty or wrong engine oil",evidence:"Level/specification/pressure abnormal",firstTest:"Verify oil and mechanical pressure where indicated"},{cause:"VVT oil-control valve or actuator fault",evidence:"Commanded and actual intake angle do not track",firstTest:"Command VVT and test its circuit/oil feed"},{cause:"Cam/crank sensor, wiring or reluctor problem",evidence:"Signal dropout, circuit code or abnormal waveform",firstTest:"Load-test circuits and scope synchronized signals"},{cause:"Repair setup, calibration or learned-value issue",evidence:"Fault appeared after ECM/engine work",firstTest:"Audit installation, calibration and required learning"}],freezeFrame:["Desired and actual intake-cam angle","RPM/load and whether code set during crank or run","Oil level, grade, temperature and pressure evidence","All VVT/cam/crank circuit companion codes","Battery voltage during start","Recent chain, head, engine or ECM work"],steps:[{title:"Listen before running",detail:"Check oil cold and stop repeated starts for persistent timing noise."},{title:"Identify the engine",detail:"Select 1ZZ, 2ZR/Valvematic, M20A or hybrid procedure by VIN."},{title:"Graph VVT response",detail:"Compare desired and actual intake angle during a safe command."},{title:"Test oil control and circuits",detail:"Inspect the valve, feed, connectors and voltage-drop results."},{title:"Compare synchronized waveforms",detail:"Separate an electrical dropout from a stable mechanical offset."},{title:"Verify timing and learning",detail:"Use engine-specific marks/tools and complete required post-repair setup."}],dontReplace:"Do not replace the cam and crank sensors as a pair because the code names both positions. A new sensor cannot correct a sticking actuator, oil-supply problem, damaged reluctor or chain installed one tooth out.",yearNotes:["1ZZ-FE, 2ZR-FE/FAE, M20A-FKS and 2ZR-FXE do not share timing marks, VVT data, torque procedures or initialization.","Valvematic-equipped 2ZR-FAE adds valve-lift control, but P0016 remains a cam-to-crank relationship fault.","Hybrid engine cycling changes when correlation can be observed; use hybrid-aware engine-run data.","No broad Toyota Corolla P0016 parts bulletin is cited; follow current VIN-specific TIS."],faqs:[{question:"Is P0016 a bad cam sensor?",answer:"Not necessarily. It is a measured relationship between camshaft and crankshaft."},{question:"Which cam is Sensor A?",answer:"It normally identifies the Bank 1 intake cam; confirm the exact engine manual."},{question:"Can wrong oil cause the code?",answer:"It can disturb VVT control, but cannot explain every mechanical correlation fault."},{question:"Can I drive?",answer:"Avoid driving until noise, oil pressure and mechanical timing are evaluated."},{question:"Can a stretched chain cause P0016?",answer:"Yes, as can incorrect installation, actuator and reluctor faults."},{question:"Why did it appear after repair?",answer:"Timing, connector placement, grounds or required learning may be wrong."},{question:"Should I replace both sensors?",answer:"No. Test circuits and synchronized waveforms first."},{question:"What proves repair?",answer:"Desired/actual angle and correlation remain correct with no pending return."}],deepDive:[{heading:"A stable offset and a signal dropout are different faults",paragraphs:["A cam signal that disappears intermittently points toward wiring, connector, sensor or reluctor integrity. Clean signals that remain consistently displaced point toward oil-controlled actuator position or mechanical timing.","Graph command and actual angle before disassembly. Those data prevent a normal sensor from being blamed for accurately reporting an out-of-time camshaft."]},{heading:"Recent repair history changes the opening tests",paragraphs:["After chain, head or engine work, verify timing marks with the correct procedure, connector identity, grounds and any learned-value initialization. Do not assume a new part was installed correctly.","Without repair history, begin with oil level/specification, VVT response and circuit evidence. Opening the timing cover before those checks wastes the code's diagnostic information."]},{heading:"Verification requires more than a quiet idle",paragraphs:["Repeat the safe rpm/temperature state from freeze frame and compare desired/actual angles. Check pending codes after the required drive or engine-run cycle.","If noise remains after the code clears, the repair is not closed. Mechanical noise deserves separate inspection even when correlation data temporarily pass."]}],sources:[manuals]}),
article({slug:"p0128",code:"P0128",title:"P0128 Code Toyota Corolla: Thermostat and Warm-Up Diagnosis",description:"Diagnose Corolla P0128 with cold-soak ECT/IAT comparison, coolant inspection, a full warm-up graph, thermostat and fan tests—without borrowing Camry fixes.",definition:"Coolant Temperature Below Thermostat Regulating Temperature",severity:"Service soon",driveAdvice:"P0128 usually allows a short diagnostic trip if coolant level is correct and temperature remains stable. Stop for a red temperature warning, steam, rapid gauge change, coolant leakage or loss of cabin heat with an empty reservoir. Never remove a pressure cap while hot.",quickAnswer:"P0128 means engine coolant did not warm as quickly or reach the range expected by the ECM. A thermostat leaking open is common, but the code does not prove it. Check coolant level cold, compare ECT and IAT with ambient after an overnight soak, graph the entire warm-up, observe radiator-hose and fan behavior, and test the ECT circuit. Toyota's 2010–2011 Camry P0128 calibration bulletin is not a Corolla bulletin and must not be applied here.",symptoms:[{key:"slow",label:"Gauge and heater warm slowly",response:"Graph ECT from a true cold start and observe when radiator flow begins."},{key:"normal",label:"Dash gauge appears normal",response:"The gauge is damped; examine scan temperature and monitor conditions."},{key:"after",label:"Code followed coolant service",response:"Inspect fill level, trapped air, thermostat orientation and connector disturbance."},{key:"cold",label:"ECT is implausible before starting",response:"Compare it with IAT and measured ambient before replacing the thermostat."},{key:"fan",label:"Cooling fan runs cold",response:"Check commands, relays and companion temperature/air-conditioning inputs."}],causes:[{cause:"Thermostat leaking or stuck open",evidence:"Slow temperature rise and premature radiator heat",firstTest:"Cold-start ECT graph with hose/thermal observation"},{cause:"Low coolant, trapped air or external leak",evidence:"Low reservoir/radiator level, heater changes or recent work",firstTest:"Cold level, pressure/leak and correct bleed inspection"},{cause:"ECT sensor or circuit biased cold",evidence:"Cold ECT disagrees with IAT/ambient",firstTest:"Cold-soak plausibility then circuit resistance/voltage test"},{cause:"Cooling fan runs when not requested",evidence:"Fan active on cold engine without valid demand",firstTest:"Compare command to relay/output operation"},{cause:"Incorrect thermostat/application or engine calibration issue",evidence:"Repair history or all physical tests pass",firstTest:"Verify VIN part and current Toyota calibration/TIS"}],freezeFrame:["ECT, IAT and ambient after overnight soak","RPM, speed and load during warm-up","Time/distance since engine start","Cooling-fan command and actual operation","Heater output and radiator-hose temperature behavior","Coolant-service and leak history"],steps:[{title:"Inspect coolant cold",detail:"Check correct reservoirs and visible leaks without opening a hot system."},{title:"Compare cold sensors",detail:"ECT and IAT should be plausible near ambient after a long soak."},{title:"Graph the whole warm-up",detail:"Watch rate of rise, thermostat opening and fan behavior."},{title:"Separate sensor from cooling hardware",detail:"Test ECT circuit and actual engine/radiator temperatures."},{title:"Confirm part and bleeding",detail:"Verify thermostat application, orientation and air removal."},{title:"Verify on the next cold start",detail:"Confirm normal warm-up and no pending P0128."}],dontReplace:"Do not replace the thermostat from the code alone and do not apply Toyota T-SB-0045-13 to a Corolla; its applicability table names specific Camry vehicles. Prove the Corolla's coolant, sensor and warm-up behavior.",yearNotes:["The widely circulated Toyota P0128 calibration bulletin T-SB-0045-13 covers specified 2010–2011 Camry 2AR-FE applications, not Corolla.","1ZZ, 2ZR, M20A and hybrid engines use different thermostats, bleed procedures and temperature specifications.","Corolla Hybrid has separate engine and inverter cooling circuits; identify the correct reservoir and warning.","No broad Corolla P0128 calibration or parts bulletin is cited."],faqs:[{question:"Does P0128 always mean a thermostat?",answer:"No. Low coolant, air, sensor bias and fan operation can cause slow measured warm-up."},{question:"Can I drive?",answer:"Usually briefly if coolant is full and temperature stable; stop for overheating or leakage."},{question:"Why is cabin heat weak?",answer:"A leaking thermostat, low coolant or air in the system can reduce heater output."},{question:"Can the dash gauge look normal?",answer:"Yes. The ECM uses more precise data than the damped gauge display."},{question:"Does the Camry bulletin apply?",answer:"No. Its published applicability does not include Corolla."},{question:"How is the thermostat tested?",answer:"Use a true cold-start graph and observe actual cooling-system temperatures/flow."},{question:"Can a bad ECT sensor cause P0128?",answer:"Yes if it reports colder than actual; cold-soak comparison helps prove it."},{question:"What proves repair?",answer:"A normal cold warm-up curve and completed monitor without pending P0128."}],deepDive:[{heading:"A genuine cold soak prevents false conclusions",paragraphs:["Before startup, ECT and IAT should be reasonably close to ambient after sitting long enough. A biased ECT can make a healthy thermostat appear slow, so capture this comparison before engine heat spreads.","Do not use a five-minute cool-down as a cold-soak test. Residual engine heat creates misleading sensor differences."]},{heading:"Watch when heat reaches the radiator",paragraphs:["A thermostat that leaks open can warm the radiator side too early and flatten the engine-temperature rise. Use safe non-contact measurement and scan data; keep hands away from fans and belts.","If temperature rises normally but the PID remains low, move toward sensor/circuit evidence. If the engine truly stays cool, inspect thermostat application, installation and fan operation."]},{heading:"Hybrid warm-up must be measured during engine run time",paragraphs:["A Corolla Hybrid may switch the gasoline engine off while the vehicle remains READY. Judge warm-up using actual engine-run data rather than elapsed trip time alone.","After repair, wait for another comparable cold start. A cleared code during a warm restart cannot verify the monitor that originally failed."]}],sources:[manuals]}),
article({slug:"p1604",code:"P1604",title:"P1604 Code Toyota Corolla: Startability Malfunction Diagnosis",description:"Diagnose Corolla P1604 from failed-start evidence: cranking voltage and speed, authorization, fuel, ignition, airflow, synchronization and compression.",definition:"Startability Malfunction",severity:"Diagnose promptly",driveAdvice:"If the Corolla starts and runs normally now, drive only as needed for diagnosis. Stop repeated cranking when battery speed falls, cables heat, fuel odor becomes strong or mechanical noise appears. Tow the vehicle if it will not start, stalls in traffic or shows oil-pressure/temperature warnings.",quickAnswer:"Toyota P1604 records that the engine failed to start normally under the ECM's monitoring conditions. It is an outcome code, not a starter, fuel-pump or ECM verdict. Reconstruct whether cranking was slow, normal with no firing, or followed by immediate stall. Then test 12-volt battery/cranking voltage, engine-speed and cam/crank synchronization, start authorization, actual fuel and pressure, ignition, MAF/throttle/purge behavior and compression. Hybrid starting requires hybrid-aware data.",symptoms:[{key:"slow",label:"Cranks slowly",response:"Test battery state and voltage-drop the starter positive and ground paths."},{key:"nostart",label:"Cranks normally but will not fire",response:"Check rpm/synchronization, authorization, fuel pressure/injector command and ignition."},{key:"stall",label:"Starts then stalls",response:"Inspect immobilizer status, throttle/airflow, purge flooding and fuel delivery."},{key:"refuel",label:"After running empty or refueling",response:"Verify actual fuel quantity/quality and purge sealing; do not trust only the gauge."},{key:"hybrid",label:"Hybrid shows READY",response:"READY does not guarantee continuous gasoline-engine operation; use hybrid engine-run data."}],causes:[{cause:"Weak battery, starter or cable voltage drop",evidence:"Low cranking voltage/speed or hot connection",firstTest:"Battery load/conductance and cranking voltage-drop tests"},{cause:"Fuel quantity, quality, pressure or injector fault",evidence:"No/low pressure, contamination or missing contribution",firstTest:"Verify actual fuel and engine-specific delivery"},{cause:"Crank/cam signal, ignition or authorization fault",evidence:"No rpm/sync/spark or immobilizer state abnormal",firstTest:"Companion codes, synchronization and authorization checks"},{cause:"Airflow, throttle or purge-flooding problem",evidence:"Post-refuel stall or implausible airflow/throttle data",firstTest:"Inspect air path and test purge sealing"},{cause:"Compression or mechanical timing failure",evidence:"Uneven cranking, correlation code or mechanical noise",firstTest:"Relative compression then mechanical testing"}],freezeFrame:["Minimum 12-volt battery voltage during crank","Cranking rpm and cam/crank synchronization","Start authorization/immobilizer status","Fuel level, pressure and injector command","MAF, MAP and throttle position","Temperature, crank duration and recent repair history"],steps:[{title:"Reconstruct the event",detail:"Record hot/cold state, crank speed/duration, fuel level and whether it started then stalled."},{title:"Preserve every companion code",detail:"Circuit, immobilizer, fuel-pressure and correlation codes outrank the outcome code."},{title:"Measure cranking quality",detail:"Test battery, starter speed and voltage drop rather than relying on sound."},{title:"Verify synchronization and authorization",detail:"Confirm ECM sees rpm/cam relationship and permits starting."},{title:"Test fuel, ignition, air and compression",detail:"Follow the branch matching the missing prerequisite."},{title:"Verify hot and cold restarts",detail:"Confirm normal start time and no pending P1604."}],dontReplace:"Do not replace the starter, fuel pump or ECM from P1604 alone. Toyota flex-fuel P1604 bulletins for Tundra and Sequoia do not include Corolla, and the 2020 Corolla campaign widely discussed online concerns P1603—not P1604.",yearNotes:["P1604 is Toyota-enhanced; a Toyota-capable scan tool may reveal start-history or subcode information absent from a basic reader.","T-SB-0166-19 and its predecessor list flex-fuel Tundra/Sequoia, not Corolla.","Toyota's certain-2020-Corolla ECU campaign identifies P1603 history, not P1604; do not merge the codes.","Corolla Hybrid starts the engine through the hybrid system and requires high-voltage safety boundaries."],faqs:[{question:"What does P1604 mean?",answer:"The ECM detected abnormal or unsuccessful engine starting performance."},{question:"Does it mean the starter is bad?",answer:"No. Battery, fuel, ignition, authorization, airflow and mechanical faults are possible."},{question:"Can a weak battery set it?",answer:"Yes, when cranking voltage or speed becomes inadequate."},{question:"Can running out of fuel cause it?",answer:"A failed start from insufficient fuel can contribute; verify actual quantity."},{question:"Is this the 2020 Corolla P1603 campaign?",answer:"No. P1603 and P1604 are different codes and conditions."},{question:"Do Tundra flex-fuel bulletins apply?",answer:"No. Their applicability does not list Corolla."},{question:"Does hybrid diagnosis differ?",answer:"Yes. READY status and engine cranking require hybrid-aware tools and safety."},{question:"What proves repair?",answer:"Reliable hot/cold restarts with normal cranking data and no pending return."}],deepDive:[{heading:"Name the failed-start pattern before choosing a test",paragraphs:["Slow cranking prioritizes battery, cables and starter load. Normal-speed cranking with no firing prioritizes synchronization, authorization, fuel and ignition. Starting then stalling changes the focus toward authorization, purge, throttle and fuel continuity.","Write down the pattern in the repair order. 'No start' alone is too vague to guide an efficient diagnosis."]},{heading:"Companion codes outrank P1604",paragraphs:["P1604 says the outcome was wrong. A crank-sensor circuit code, low fuel-pressure code or immobilizer status can say which prerequisite disappeared. Save everything before clearing or charging the battery.","If the tank ran dry or a repair introduced the event, correct that known condition and still verify normal cranking/fuel data. An explained event does not justify unrelated parts."]},{heading:"Avoid two common Corolla bulletin mistakes",paragraphs:["Do not apply the Tundra/Sequoia alcohol-density P1604 bulletin to Corolla. Do not convert Toyota's P1603 low-speed-stall campaign into a P1604 campaign because the numbers look similar.","Check the VIN for actual campaigns separately, then diagnose the stored code using its own definition and evidence."]}],sources:[manuals]}),
article({slug:"p0101",code:"P0101",title:"P0101 Code Toyota Corolla: MAF Range and Airflow Diagnosis",description:"Diagnose Corolla P0101 through filter and duct inspection, smoke testing, MAF/MAP/throttle cross-checks, fuel trims and engine-breathing tests.",definition:"Mass or Volume Air Flow Circuit Range/Performance",severity:"Diagnose promptly",driveAdvice:"Avoid hard acceleration if the Corolla hesitates, runs rich or lean, or enters reduced-power operation. Stop for stalling in traffic, a flashing misfire lamp, heavy black smoke or overheating. A stable car with a steady lamp may be driven a short distance for testing.",quickAnswer:"P0101 means the MAF signal did not agree with airflow the ECM expected from rpm, throttle, pressure and operating state. The code is a plausibility failure, not proof of a dirty sensor. Inspect the exact filter and airbox assembly, duct and clamps; check modifications; smoke-test downstream air/PCV paths; compare MAF, MAP, throttle, load and fuel trims; then test the MAF circuit. Purge flow, VVT, Valvematic or mechanical breathing can also disturb the model.",symptoms:[{key:"service",label:"Code followed air-filter service",response:"Check filter fit, housing closure, duct seating, clamps and connector pins."},{key:"idle",label:"Rough idle with positive trims",response:"Smoke-test the metered-air path, PCV and purge sealing."},{key:"load",label:"Poor power under load",response:"Inspect restriction and graph airflow against rpm/load without using a universal number."},{key:"rich",label:"Black smoke or negative trims",response:"Test airflow bias, fuel pressure/injectors and purge."},{key:"bump",label:"Intermittent on bumps",response:"Inspect pin fit, harness strain and grounds while graphing the signal."}],causes:[{cause:"Loose/split duct or unmetered-air leak",evidence:"Smoke leakage or trim strongest at idle",firstTest:"Inspect then regulated smoke-test downstream of MAF"},{cause:"Wrong, restricted or poorly seated filter/airbox",evidence:"Recent service or restriction evidence",firstTest:"Verify part, orientation and clean/dirty-side sealing"},{cause:"Biased/contaminated MAF or circuit fault",evidence:"Controlled response or electrical test fails",firstTest:"Power, ground, signal and plausibility tests"},{cause:"MAP, throttle or purge input distorts airflow model",evidence:"Companion codes or commanded response mismatch",firstTest:"Cross-check related sensors and purge sealing"},{cause:"VVT, Valvematic, compression or exhaust restriction",evidence:"Airflow remains abnormal after intake/electronics pass",firstTest:"Engine-breathing, valve-control and backpressure tests"}],freezeFrame:["MAF units/value, rpm and calculated load","MAP/barometric pressure and throttle angle","Short- and long-term fuel trim","Coolant/intake temperature and battery voltage","Purge command and companion P0171/VVT codes","Filter/intake modification and service history"],steps:[{title:"Save simultaneous airflow data",detail:"Record units and related PIDs, not an isolated MAF number."},{title:"Verify parts and assembly",detail:"Inspect filter, airbox, duct, clamps and modifications."},{title:"Smoke-test downstream paths",detail:"Include PCV and brake-booster plumbing where fitted."},{title:"Cross-check sensors",detail:"Compare KOEO MAP/barometric plausibility and warm MAF/MAP/throttle/load."},{title:"Test circuit and engine breathing",detail:"Proceed to electronics/VVT/compression only after physical checks."},{title:"Verify across a safe airflow range",detail:"Confirm normal agreement and no pending P0101."}],dontReplace:"Do not replace or repeatedly clean the MAF because P0101 names it. A performance code can be created by intake assembly, leaks, other sensor inputs, purge, valve-control or mechanical airflow.",yearNotes:["Expected airflow changes with 1ZZ, 2ZR and M20A displacement/design, rpm, altitude and temperature; one internet grams-per-second rule is not sufficient.","2ZR-FAE Valvematic and M20A Dynamic Force control airflow differently from older throttle-only engines.","Aftermarket oiled filters and intake tubes can contaminate or rescale metering and should be disclosed.","No broad Corolla P0101 parts bulletin is cited."],faqs:[{question:"Does P0101 mean the MAF is bad?",answer:"No. It means measured airflow failed a plausibility check."},{question:"Can an intake leak cause it?",answer:"Yes, especially downstream of the MAF."},{question:"Can I clean the MAF?",answer:"Only with an approved method after inspection; cleaning is not a circuit test."},{question:"Can a dirty filter cause P0101?",answer:"Severe restriction or incorrect installation can contribute."},{question:"Can purge cause it?",answer:"Unexpected vapor/air flow can upset the airflow model."},{question:"Can Valvematic or VVT matter?",answer:"Yes, valve-control faults can change actual engine breathing."},{question:"What data should be graphed?",answer:"MAF, MAP, throttle, load, rpm and fuel trims on the same timeline."},{question:"What proves repair?",answer:"Plausible airflow in the original condition with no pending code."}],deepDive:[{heading:"A rationality code uses several witnesses",paragraphs:["At key-on engine-off, MAP should be plausible against local barometric pressure. At warm idle and safe higher airflow, MAF, MAP, throttle, load and trims should tell one consistent story.","A MAF can produce a voltage inside its electrical range yet be biased. Conversely, a healthy MAF can report correctly while air enters downstream or engine breathing changes."]},{heading:"Start with what was touched",paragraphs:["If P0101 followed filter service, inspect the airbox tabs, filter seal, duct clamps and connector before cleaning anything. A small assembly error can alter both metered flow and fuel trims.","If aftermarket intake parts are installed, compare geometry and sensor orientation with stock. Physical fit does not guarantee calibration compatibility."]},{heading:"Cleaning is maintenance, not proof",paragraphs:["Use only an approved sensor-safe process and never touch the sensing element. A temporary change after cleaning may support contamination but does not test wiring or downstream leaks.","Close the diagnosis by repeating the freeze-frame airflow range and inspecting pending codes. A normal idle alone cannot disprove a load-dependent rationality fault."]}],sources:[manuals]}),
article({slug:"p0138",code:"P0138",title:"P0138 Code Toyota Corolla: Downstream O2 High-Voltage Diagnosis",description:"Diagnose Corolla P0138 by confirming Bank 1 Sensor 2, testing downstream wiring and response, and separating true rich exhaust from sensor bias.",definition:"Oxygen Sensor Circuit High Voltage (Bank 1, Sensor 2)",severity:"Service soon",driveAdvice:"P0138 alone usually allows a short diagnostic trip. Stop for a flashing misfire lamp, raw-fuel odor, black smoke, an overheating catalyst or severe rough running. Genuine rich operation can damage the converter quickly even when the code names a sensor circuit.",quickAnswer:"P0138 means the Bank 1 downstream oxygen-sensor signal stayed above the range or response expected by the ECM. On a Corolla inline-four, Bank 1 is the only bank and Sensor 2 sits downstream of the catalyst. The code does not prove the sensor or converter failed. Test actual mixture, purge and fuel delivery, inspect exhaust and connector routing, then evaluate the Sensor 2 signal and circuit for a short or bias. Toyota's multi-model P0138 bulletins found online do not list Corolla.",symptoms:[{key:"rich",label:"Black smoke or fuel odor",response:"Stop prolonged driving and diagnose actual rich fueling before sensor replacement."},{key:"after",label:"Code followed exhaust work",response:"Verify Sensor 2 identity, connector placement, harness routing and exhaust sealing."},{key:"fixed",label:"Signal high with engine off",response:"Test for a circuit short or contamination before condemning the sensor."},{key:"codes",label:"Rich or purge codes also present",response:"Treat mixture control as the likely upstream influence."},{key:"alone",label:"No drivability symptoms",response:"Graph downstream response and perform circuit tests under the setting condition."}],causes:[{cause:"Downstream oxygen sensor internally biased",evidence:"Circuit/exhaust/mixture pass but controlled sensor response fails",firstTest:"Toyota-specified response test"},{cause:"Signal wire shorted to voltage or damaged by heat",evidence:"High signal persists in circuit isolation test",firstTest:"Inspect routing and load-test signal/ground"},{cause:"Actual rich exhaust from fuel pressure/injector",evidence:"Negative trims, smoke, deposits or rich codes",firstTest:"Test fuel pressure and injector leakage"},{cause:"Purge valve feeding excessive vapor",evidence:"Post-refuel symptom or flow commanded off",firstTest:"Independent purge sealing test"},{cause:"Crossed connector, exhaust leak or service error",evidence:"Recent sensor/exhaust work",firstTest:"Verify component identity, pins and exhaust integrity"}],freezeFrame:["Bank 1 Sensor 2 value and response","Upstream A/F-sensor data","Short- and long-term fuel trim","RPM, load, coolant temperature and speed","Purge command and time since refueling","Recent exhaust/sensor work and companion codes"],steps:[{title:"Confirm sensor identity",detail:"Map Bank 1 Sensor 2 for the exact year and engine."},{title:"Save mixture context",detail:"Record trims, upstream A/F data and all companion codes."},{title:"Inspect exhaust and wiring",detail:"Look for leaks, heat damage, crossed connectors and pin faults."},{title:"Test actual rich operation",detail:"Evaluate fuel pressure, injector leakage and purge sealing."},{title:"Test downstream circuit/response",detail:"Use controlled Toyota procedures instead of parts swapping."},{title:"Verify the original state",detail:"Confirm normal response and no pending P0138."}],dontReplace:"Do not replace the downstream sensor, converter or ECM from one P0138. Prove whether the exhaust is genuinely rich and whether the circuit or sensor fails a controlled test. Toyota T-SB-0001-10 and T-SB-0151-18 do not list Corolla in their applicability tables.",yearNotes:["Corolla inline-four engines have one bank; Sensor 2 is downstream of the catalyst, but connector routing varies by generation.","Toyota T-SB-0001-10 covers listed Avalon/Camry/Highlander/RAV4/Sienna/Venza applications—not Corolla.","Toyota T-SB-0151-18 covers specified Camry and RAV4 2AR applications—not Corolla.","Later air/fuel and oxygen-sensor data definitions require the exact Corolla repair manual."],faqs:[{question:"What is Bank 1 Sensor 2?",answer:"It is the downstream oxygen sensor after the catalyst on the Corolla's only bank."},{question:"Does P0138 mean the sensor is bad?",answer:"Not automatically. Rich exhaust and wiring faults can hold the signal high."},{question:"Does it mean the converter is bad?",answer:"No. P0138 is a sensor-circuit/response code, not catalyst-efficiency code P0420."},{question:"Can a leaking injector cause it?",answer:"Yes, if it creates genuinely rich exhaust."},{question:"Can purge cause P0138?",answer:"Excessive vapor flow can enrich the mixture and influence the sensor."},{question:"Do Toyota RAV4/Camry bulletins apply?",answer:"No. Their published applicability does not include Corolla."},{question:"Can I drive?",answer:"Usually briefly if alone; stop for raw fuel, smoke or flashing misfire."},{question:"What proves repair?",answer:"Normal controlled Sensor 2 response, corrected mixture/circuit and no pending P0138."}],deepDive:[{heading:"First decide whether the exhaust is actually rich",paragraphs:["Negative fuel trims, fuel odor, sooty plugs and rich companion codes move fuel pressure, injector leakage and purge above the downstream sensor. Normal mixture data moves wiring and sensor response higher.","Do not rely on tailpipe appearance alone. Use live fuel control and controlled tests so a circuit short is not mistaken for excess fuel—or vice versa."]},{heading:"Why Bank 1 Sensor 2 identification still matters on an inline-four",paragraphs:["There is only one bank, but upstream A/F and downstream O2 connectors can be routed close together. Recent exhaust or engine work can create crossed, stretched or heat-damaged connections.","Confirm the component and pinout by VIN before resistance or voltage testing. Applying current to the wrong circuit can damage an ECM input."]},{heading:"Reject the wrong Toyota bulletin",paragraphs:["Search engines often return Toyota P0138 bulletins for RAV4 and Camry because they share brand terminology. Applicability tables are part of the diagnosis; neither cited multi-model path makes a Corolla repair valid.","For Corolla, complete the current TIS diagnostic and document the failed circuit, response or mixture test. That specificity is stronger than borrowed bulletin authority."]}],sources:[manuals]}),
];
